    cur:{nom:'numen'},
    fire:{aria:'Stoke Vesta’s flame',hint:'Click the flame to feed it.',start:'Vesta’s flame is burning. The night in Rome has begun.'},
    spiritsTitle:'Gods', glyphTitle:'Roman numeral',
    spirits:[
      ['Lares','household gods','Little gods of the hearth. Every house has its lararium.',[['Lararium','A small shrine in the atrium'],['Cakes and wine','An offering on the Kalends']],'The Lares have moved into the lararium.'],
      ['Penates','guardians of the pantry','They guard the household stores. Without them there is no bread.',[['Full pantry','Flour, oil and wine'],['Salt on the table','An offering at every meal']],'The pantry fills itself. The Penates are here.'],
      ['Faunus','god of the woods','Guards flocks and forests and whispers prophecies in the rustling leaves.',[['Lupercalia','A festival in February'],['Whispering leaves','Prophecy from the forest']],'A whisper comes from the forest. Faunus has joined you.'],
      ['Janus','god of beginnings','Has two faces: one looks to the past, the other to the future.',[['Two faces','He sees what was and what will be'],['Temple doors','Open in war, closed in peace']],'The doors open by themselves. Janus watches you with both faces.'],
      ['Ceres','goddess of the harvest','Gives grain and fertile fields. Her gifts feed Rome.',[['Golden ears of wheat','The first fruits of the harvest'],['Cerealia','Games in her honour']],'The fields turn gold. Ceres is on your side.'],
      ['Neptune','god of the sea','Lord of the sea and of horses. When he is angry, the sea rises.',[['Trident','It calms and wakes the waves'],['Neptunalia','A summer festival in July']],'The waves grow calm. Neptune has arrived.'],
      ['Minerva','goddess of wisdom','Patron of crafts and wisdom, one of the three gods of the Capitol.',[['Owl','Wisdom in the dark'],['Quinquatria','A festival in March']],'An owl lands on the temple. Minerva is with you.'],
      ['Mars','god of war','Father of Romulus and Remus, protector of Rome and its fields.',[['Sacred spear','Kept in the Regia'],['Field of Mars','Where the soldiers train']],'A trumpet sounds from the Field of Mars. Mars is with you.'],
      ['Jupiter','king of the gods','Jupiter Optimus Maximus, best and greatest, lord of the Capitol and the thunderbolt.',[['Capitoline temple','The holiest place in Rome'],['Legion eagle','It carries his thunderbolt']],'Lightning over the Capitol. Jupiter has noticed you. The great battle is now possible.'],
    ],
    clicks:[['Flint and steel','Clicks give twice as much.'],['Oak logs','For a flame that never goes out. Clicks give twice as much.'],['Mola salsa','Salted flour prepared by the Vestals. Each click also gives 1% of your numen per second.'],['Parilia','A festival where people leap over fires. Each click gives another 2% of your numen per second.'],['Fasces','A bundle of rods with an axe. Clicks give five times as much.']],
    bells:['Dance of the Salii','Priests dance with the sacred shields. Your bolts hit Cacus twice as hard.','Salii'],
    bonus:{name:'Ancile',toast:'A sacred shield has fallen from the sky into the fire! Take it before it vanishes.',buff:'The ancile is yours. Everything gathers seven times faster.',treasure:'The ancile showed you buried treasure: {x} numen.'},
    raid:{who:'Cacus',head:'Cacus is climbing the Aventine',sub:'While he climbs he takes a quarter of your numen. Drive him back before he reaches the top.',ends:['cave','Aventine'],
      strike:'Hurl a thunderbolt',helper:'Mars',fin:['Jupiter’s thunderbolt','Jupiter banishes him at once'],
      start:'Cacus, son of Vulcan, is climbing the Aventine! Drive him back before he reaches the top.',
      flee:'Cacus was driven back into his cave. +{x} numen.',
      finFlee:'Jupiter’s thunderbolt struck him and Cacus fled into his cave. +{x} numen.',
      win:'Cacus reached the top of the Aventine and dragged {x} numen into his cave.',lost:'Cacus got away with {x} numen.'},
    prestige:{name:'Laurel wreaths',each:'Each wreath',short:'laurels'},
    battle:{name:'The Fall of Cacus',copy:'Jupiter is with you. Pour enough numen into the battle and help Rome be rid of the giant Cacus for good.',
      lines:['Cacus storms out of his cave, breathing fire and smoke across the Aventine.','Jupiter hurls his bolts, and Hercules tears the rock from the roof of the cave.','Light floods the darkness and Cacus has nowhere left to hide.','Cacus falls. Rome raises a great altar, the Ara Maxima, to mark the victory.'],
      victory:'Rome is saved. Jupiter’s blessing doubles all numen forever. Cacus will attack no more.',
      blessing:'Jupiter’s blessing', after:'Cacus is defeated and the Aventine is at peace.'},
